#!/usr/bin/env bash
# THE ACTUAL BUG causing "registration not confirmed" on Windows, found by
# running the agent in the foreground (python opslab_agent_service.py run)
# instead of guessing from the 15s timeout message:
#
#     ModuleNotFoundError: No module named 'requests'
#
# requirements.txt never listed 'requests', even though agent/api_client.py
# has always needed it. install.ps1's step 5 (`pip install -r
# requirements.txt`) installs into the agent's bundled Python runtime on
# every fresh Windows enrollment, so every install has been missing this
# dependency from the start - unrelated to the two earlier fixes in this
# series (the missing commands.py channel, and the sys.path
# ModuleNotFoundError for the agent package itself). Fixed by adding
# requests==2.32.3 to requirements.txt.
#
# Updates BOTH this repo's own ./requirements.txt, ./agent, and
# ./service_files (what build_msi_selfcontained.sh / build_msi.sh / the exe
# builder stage from directly) AND the served
# app/static/installers/opslab-agent.tar.gz (what install.ps1 downloads for
# a fresh enrollment). Also includes the two earlier fixes (commands.py
# channel + sys.path fix) in case this is being run standalone.
#
# Run from inside /root/admin_panel (or wherever this repo lives on the VPS).
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> [1/3] Extracting fixed agent/ + requirements.txt + service_files/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'B64_EOF_MARKER'

B64_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "^requests" "$TMP_EXTRACT/requirements.txt"; then
    echo "    ERROR: fix not found in the extracted payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
cp -f "$TMP_EXTRACT/service_files/windows/opslab_agent_service.py" service_files/windows/opslab_agent_service.py
cp -f "$TMP_EXTRACT/requirements.txt" requirements.txt
echo "    Updated agent/*.py, service_files/windows/opslab_agent_service.py, and requirements.txt in this repo."

echo "==> [2/3] Rewriting app/static/installers/opslab-agent.tar.gz"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> [3/3] Verifying the served tarball"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    tarball is readable"
VERIFY_DIR="$(mktemp -d)"
tar -xzf app/static/installers/opslab-agent.tar.gz -C "$VERIFY_DIR"
if grep -q "^requests" "$VERIFY_DIR/requirements.txt"; then
    echo "    Confirmed: requests is now in the packaged requirements.txt."
else
    echo "    ERROR: fix not found in the packaged tarball!"
    rm -rf "$VERIFY_DIR"
    exit 1
fi
rm -rf "$VERIFY_DIR"

echo ""
echo "This fix does NOT need an app restart (it only affects what install.ps1"
echo "installs on the Windows machine going forward) - but restarting is harmless"
echo "if you want to be thorough:"
echo "    pkill -f 'admin_panel/run.py'; fuser -k 6090/tcp 2>/dev/null"
echo "    cd /root/admin_panel && source venv/bin/activate && nohup python run.py > app.log 2>&1 & disown"
echo ""
echo "On the Windows machine, just re-run the enrollment command with a fresh token"
echo "(install.ps1 re-downloads the Python runtime and reinstalls requirements.txt"
echo "from scratch every run, so no manual uninstall is needed):"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <fresh-token> -AdminUrl https://kiosksys.opslabsystems.cloud"
